const businessDate = $now.setZone('Asia/Vladivostok').toFormat('yyyy-MM-dd');
return [{ json: {
  triggered_at: $now.toISO(),
  business_date: businessDate,
  timezone: 'Asia/Vladivostok',
  rule_version: 'daily-plan-rules-v1',
  task_id: `daily-plan:${businessDate}:v1`,
  scenario: $env.LE_TEST_SCENARIO ?? 'normal'
} }];

const state = $getWorkflowStaticData('node');
state.readAttempts = (state.readAttempts ?? 0) + 1;
if ($json.scenario === 'transient_failure' && state.readAttempts === 1) {
  throw new Error('SIMULATED_HTTP_503');
}
if ($json.scenario === 'persistent_failure') {
  throw new Error('SIMULATED_HTTP_503_PERSISTENT');
}
const tasks = [
  { id: 'T-104', title: '确认发布范围', status: 'open', due_at: `${$json.business_date}T18:00:00+10:00`, owner: 'user-01', waiting_on: null, updated_at: `${$json.business_date}T07:50:00+10:00`, source_url: 'https://example.invalid/tasks/T-104' },
  { id: 'T-207', title: '等待客户确认', status: 'in_progress', due_at: `${$json.business_date}T09:00:00+10:00`, owner: 'user-01', waiting_on: 'customer-a', updated_at: `${$json.business_date}T07:45:00+10:00`, source_url: 'https://example.invalid/tasks/T-207' },
  { id: 'T-301', title: '补全复盘记录', status: 'open', due_at: null, owner: null, waiting_on: null, updated_at: `${$json.business_date}T07:40:00+10:00`, source_url: 'https://example.invalid/tasks/T-301' }
];
return [{ json: { ...$json, source_read_at: $now.toISO(), source_version: 'fixture-v1', tasks } }];

const busySlots = [
  { start: `${$json.business_date}T10:00:00+10:00`, end: `${$json.business_date}T11:00:00+10:00` }
];
return [{ json: { ...$json, busy_slots: busySlots, calendar_read_at: $now.toISO() } }];

const allowed = ['id','title','status','due_at','owner','waiting_on','updated_at','source_url'];
const sanitized = $json.tasks.map((task) => Object.fromEntries(allowed.map((key) => [key, task[key] ?? null])));
const eligible = sanitized.filter((task) => !['completed','cancelled'].includes(task.status));
const excluded_items = sanitized.filter((task) => ['completed','cancelled'].includes(task.status)).map((task) => ({ source_id: task.id, title: task.title, reason: `状态为 ${task.status}` }));
return [{ json: { ...$json, tasks: sanitized, eligible, excluded_items } }];

const state = $getWorkflowStaticData('global');
state.tasks ??= {};
const existing = state.tasks[$json.task_id];
if (existing && ['awaiting_review','completed'].includes(existing.status)) {
  existing.duplicate_trigger_count = (existing.duplicate_trigger_count ?? 0) + 1;
  return [];
}
state.tasks[$json.task_id] = { task_id: $json.task_id, status: 'discovered', rule_version: $json.rule_version, business_date: $json.business_date };
return [{ json: { ...$json, task_status: 'discovered' } }];

const item = (task, reason) => ({ source_id: task.id, title: task.title, reason });
const draft = { priority_items: [], schedulable_items: [], missing_information: [], excluded_items: [...$json.excluded_items], warnings: [] };
for (const task of $json.eligible) {
  if (!task.owner || !task.due_at) draft.missing_information.push(item(task, '负责人或截止缺失'));
  else if (task.waiting_on) draft.schedulable_items.push(item(task, `等待 ${task.waiting_on}，只允许生成跟进建议`));
  else if (task.due_at.slice(0, 10) <= $json.business_date) draft.priority_items.push(item(task, '已到期且当前可行动'));
  else draft.schedulable_items.push(item(task, '未到期，可安排'));
}
return [{ json: { ...$json, draft } }];

const required = ['priority_items','schedulable_items','missing_information','excluded_items','warnings'];
const keys = Object.keys($json.draft);
for (const key of required) if (!Array.isArray($json.draft[key])) throw new Error(`SCHEMA_MISSING_OR_INVALID:${key}`);
for (const key of keys) if (!required.includes(key)) throw new Error(`SCHEMA_UNKNOWN_FIELD:${key}`);
for (const group of required.slice(0, 4)) {
  for (const item of $json.draft[group]) {
    const itemKeys = Object.keys(item);
    if (!['source_id','title','reason'].every((key) => typeof item[key] === 'string' && item[key])) throw new Error(`SCHEMA_INVALID_ITEM:${group}`);
    if (itemKeys.some((key) => !['source_id','title','reason'].includes(key))) throw new Error(`SCHEMA_UNKNOWN_ITEM_FIELD:${group}`);
  }
}
return [{ json: { ...$json, schema_validation: { passed: true, schema_version: 'draft-2020-12-v1' } } }];

const handled = new Set(['priority_items','schedulable_items','missing_information','excluded_items'].flatMap((field) => $json.draft[field].map((item) => item.source_id)));
const expected = new Set($json.tasks.map((task) => task.id));
const missing = [...expected].filter((id) => !handled.has(id));
if (missing.length) throw new Error(`DETERMINISTIC_COVERAGE_FAILED:${missing.join(',')}`);
return [{ json: { ...$json, deterministic_checks: { passed: true, rule_ids: ['coverage-v1','identity-v1','waiting-v1'] } } }];

const crypto = require('crypto');
const artifactVersion = `${$json.run_id}:draft:v1`;
const artifactHash = crypto.createHash('sha256').update(JSON.stringify($json.draft)).digest('hex');
return [{ json: { ...$json, artifact_version: artifactVersion, artifact_hash: artifactHash, artifact_saved_at: $now.toISO() } }];

const decision = $json.approval.decision;
const nextState = decision === 'approved' ? 'completed' : decision === 'rejected' ? 'rejected' : decision === 'modified' ? 'running' : 'awaiting_review';
if (decision === 'approved' && ($json.approval.artifact_version !== $json.artifact_version || $json.approval.artifact_hash !== $json.artifact_hash)) throw new Error('STALE_APPROVAL');
return [{ json: { ...$json, next_state: nextState } }];

const state = $getWorkflowStaticData('global');
if (state.tasks?.[$json.task_id]) {
  state.tasks[$json.task_id].status = $json.next_state;
  state.tasks[$json.task_id].current_run_id = $json.run_id;
  state.tasks[$json.task_id].artifact_version = $json.artifact_version;
  state.tasks[$json.task_id].artifact_hash = $json.artifact_hash;
}
return [{ json: { task_id: $json.task_id, run_id: $json.run_id, status: $json.next_state, artifact_version: $json.artifact_version, artifact_hash: $json.artifact_hash, schema_validation: $json.schema_validation, deterministic_checks: $json.deterministic_checks, warnings: $json.draft.warnings } }];
